"""验证迁移门禁能接受基线并拒绝并行分叉。"""

from pathlib import Path
from io import StringIO

import pytest
from alembic import command
from alembic.config import Config

from scripts.check_migrations import check_migrations

ROOT = Path(__file__).resolve().parents[2]


def test_repository_migration_chain() -> None:
    """真实迁移目录有且仅有一条可遍历版本链。"""
    assert check_migrations(Config(str(ROOT / "alembic.ini"))) == 1


def test_migration_fork_is_rejected(tmp_path: Path) -> None:
    """模拟两组从同一版本新建迁移，确保门禁确实拒绝多头。"""
    versions = tmp_path / "versions"
    versions.mkdir()
    for revision, parent in [("base", None), ("left", "base"), ("right", "base")]:
        (versions / f"{revision}.py").write_text(
            "# AI-generated file.\n# Generated by Codex(GPT) in 2026-10-30 15:34.\n"
            f"revision = {revision!r}\ndown_revision = {parent!r}\n",
            encoding="utf-8",
        )
    config = Config()
    config.set_main_option("script_location", str(tmp_path))
    with pytest.raises(ValueError, match="one base and one head"):
        check_migrations(config)


@pytest.mark.parametrize("url", [None, "sqlite:///wrong.db"])
def test_migration_requires_explicit_postgres(monkeypatch, url: str | None) -> None:
    """缺少配置或试图用 SQLite 替代 PostgreSQL 时明确失败。"""
    if url is None:
        monkeypatch.delenv("DATABASE_URL", raising=False)
    else:
        monkeypatch.setenv("DATABASE_URL", url)
    config = Config(str(ROOT / "alembic.ini"), output_buffer=StringIO())
    with pytest.raises((RuntimeError, ValueError), match="DATABASE_URL|PostgreSQL"):
        command.upgrade(config, "head", sql=True)


def test_offline_sql_does_not_expose_credentials(monkeypatch) -> None:
    """离线 SQL 可审查且不包含 URL 中的密码。"""
    monkeypatch.setenv("DATABASE_URL", "postgresql://test:secret-never-print@localhost/test")
    output = StringIO()
    command.upgrade(Config(str(ROOT / "alembic.ini"), output_buffer=output), "head", sql=True)
    assert "CREATE EXTENSION IF NOT EXISTS vector" in output.getvalue()
    assert "secret-never-print" not in output.getvalue()
